  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #131a2e;
      --panel-2: #1a2340;
      --border: #314062;
      --text: #f3f6ff;
      --muted: #b5c0df;
      --accent: #7c9cff;
      --accent-2: #9e7dff;
      --shadow: 0 18px 45px rgba(0, 0, 0, 0.35);
      --radius: 18px;
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, #18203b 0%, transparent 42%),
        linear-gradient(180deg, #070b16 0%, var(--bg) 100%);
      color: var(--text);
      line-height: 1.5;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      transform: translateY(-200%);
      background: var(--accent);
      color: #09111f;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      text-decoration: none;
      font-weight: 700;
      z-index: 20;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    main {
      width: min(900px, calc(100% - 2rem));
      margin: 0 auto;
      padding: 4rem 0 3rem;
    }

    .quiz-shell {
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.03), rgba(255, 255, 255, 0.01));
      border: 1px solid var(--border);
      border-radius: calc(var(--radius) + 6px);
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .hero {
      padding: 2rem 2rem 1.25rem;
      background:
        linear-gradient(135deg, rgba(124, 156, 255, 0.18), rgba(158, 125, 255, 0.08)),
        var(--panel);
      border-bottom: 1px solid var(--border);
    }

    h1 {
      margin: 0 0 0.5rem;
      font-size: clamp(1.8rem, 3vw, 2.6rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0;
      max-width: 62ch;
      color: var(--muted);
    }

    form {
      padding: 1.25rem;
    }

    .form-field + .form-field {
      margin-top: 1rem;
    }

    fieldset {
      margin: 0;
      padding: 1.25rem;
      border: 1px solid var(--border);
      border-radius: var(--radius);
      background: linear-gradient(180deg, var(--panel-2), rgba(255, 255, 255, 0.02));
      min-width: 0;
    }

    legend {
      padding: 0 0.5rem;
      font-size: 1.05rem;
      font-weight: 700;
    }

    .help-text {
      margin: 0.35rem 0 1rem;
      color: var(--muted);
    }

    .options {
      display: grid;
      gap: 0.75rem;
    }

    .option {
      display: flex;
      align-items: flex-start;
      gap: 0.75rem;
      padding: 0.9rem 1rem;
      border: 1px solid var(--border);
      border-radius: 14px;
      background: rgba(9, 14, 27, 0.45);
      transition: border-color 0.2s ease, background-color 0.2s ease, transform 0.2s ease;
    }

    .option:hover {
      border-color: #4e67a3;
      background: rgba(16, 23, 42, 0.75);
      transform: translateY(-1px);
    }

    .option input {
      margin-top: 0.2rem;
      width: 1.05rem;
      height: 1.05rem;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    .option-label {
      display: grid;
      gap: 0.15rem;
      cursor: pointer;
    }

    .option-title {
      font-weight: 600;
    }

    .option-note {
      color: var(--muted);
      font-size: 0.95rem;
    }

    .actions {
      display: flex;
      justify-content: flex-end;
      padding: 1rem 1.25rem 1.25rem;
      gap: 0.75rem;
    }

    button {
      appearance: none;
      border: 1px solid transparent;
      border-radius: 999px;
      padding: 0.9rem 1.3rem;
      font: inherit;
      font-weight: 700;
      color: #08101d;
      background: linear-gradient(135deg, var(--accent), var(--accent-2));
      cursor: pointer;
      box-shadow: 0 12px 28px rgba(124, 156, 255, 0.25);
    }

    button:hover {
      filter: brightness(1.05);
    }

    button:focus-visible,
    input:focus-visible,
    .skip-link:focus-visible {
      outline: 3px solid #ffffff;
      outline-offset: 3px;
    }

    .result {
      margin: 0 1.25rem 1.25rem;
      padding: 1rem 1.1rem;
      border: 1px solid var(--border);
      border-radius: 14px;
      background: rgba(11, 16, 32, 0.8);
      color: var(--muted);
      min-height: 3.25rem;
    }

    .result strong {
      color: var(--text);
    }

    @media (max-width: 640px) {
      main {
        width: min(100% - 1rem, 900px);
        padding: 3.5rem 0 2rem;
      }

      .hero,
      form,
      .result {
        padding-left: 1rem;
        padding-right: 1rem;
      }

      fieldset {
        padding: 1rem;
      }

      .actions {
        justify-content: stretch;
      }

      button {
        width: 100%;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --panel: Canvas;
        --panel-2: Canvas;
        --border: ButtonBorder;
        --text: CanvasText;
        --muted: CanvasText;
        --accent: Highlight;
        --accent-2: Highlight;
      }

      .skip-link,
      .quiz-shell,
      fieldset,
      .option,
      .result,
      button {
        forced-color-adjust: auto;
      }

      .option input {
        accent-color: auto;
      }
    }
  </style>
</head>
