                <input type="checkbox" name="q1" value="java" />
                <span class="option-label">
                  <span class="option-title">Java</span>
                  <span class="option-note">Common in enterprise software and Android.</span>
                </span>
              </label>
              <label class="option">
                <input type="checkbox" name="q1" value="html" />
                <span class="option-label">
                  <span class="option-title">HTML</span>
                  <span class="option-note">A markup language for structuring web content.</span>
                </span>
              </label>
              <label class="option">
                <input type="checkbox" name="q1" value="csharp" />
                <span class="option-label">
                  <span class="option-title">C#</span>
                  <span class="option-note">Often used for desktop, web, and game development.</span>
                </span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend>2. Which languages are commonly used for web development?</legend>
            <div class="options">
              <label class="option">
                <input type="checkbox" name="q2" value="javascript" />
                <span class="option-label">
                  <span class="option-title">JavaScript</span>
                  <span class="option-note">Adds interactivity in browsers and on servers.</span>
                </span>
              </label>
              <label class="option">
                <input type="checkbox" name="q2" value="css" />
                <span class="option-label">
                  <span class="option-title">CSS</span>
                  <span class="option-note">Styles the look and layout of web pages.</span>
                </span>
              </label>
              <label class="option">
                <input type="checkbox" name="q2" value="ruby" />
                <span class="option-label">
                  <span class="option-title">Ruby</span>
                  <span class="option-note">Popular for backend web frameworks.</span>
                </span>
              </label>
              <label class="option">
                <input type="checkbox" name="q2" value="sql" />
                <span class="option-label">
                  <span class="option-title">SQL</span>
                  <span class="option-note">Used to query and manage relational databases.</span>
                </span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend>3. Which languages are known for compiled performance?</legend>
            <div class="options">
              <label class="option">
                <input type="checkbox" name="q3" value="c" />
                <span class="option-label">
                  <span class="option-title">C</span>
                  <span class="option-note">A classic systems programming language.</span>
                </span>
              </label>
              <label class="option">
                <input type="checkbox" name="q3" value="rust" />
                <span class="option-label">
                  <span class="option-title">Rust</span>
                  <span class="option-note">Known for safety and high performance.</span>
                </span>
              </label>
              <label class="option">
                <input type="checkbox" name="q3" value="swift" />
                <span class="option-label">
                  <span class="option-title">Swift</span>
                  <span class="option-note">Used heavily in Apple platform development.</span>
                </span>
              </label>
              <label class="option">
                <input type="checkbox" name="q3" value="perl" />
                <span class="option-label">
                  <span class="option-title">Perl</span>
                  <span class="option-note">Flexible language with strong text-processing tools.</span>
                </span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Submit answers</button>
        </div>

        <p class="result" id="result" aria-live="polite">Your answers will appear here after you submit.</p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('quiz-form');
    const result = document.getElementById('result');

    const labels = {
      q1: 'Question 1',
      q2: 'Question 2',
      q3: 'Question 3'
    };

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      const parts = Object.keys(labels).map((name) => {
        const selected = [...form.querySelectorAll(`input[name="${name}"]:checked`)]
          .map((input) => input.parentElement.querySelector('.option-title').textContent);

        return `${labels[name]}: ${selected.length ? selected.join(', ') : 'no choices selected'}`;
      });

      result.innerHTML = `<strong>Submitted.</strong> ${parts.join(' | ')}`;
    });
  </script>
</body>
